const out=(data:unknown,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'no-store'}});
function db(){return context.db as D1Database}
async function role(r:Request){const id=r.headers.get('oai-authenticated-user-id'),email=r.headers.get('oai-authenticated-user-email')?.toLowerCase();if(!id||!email)return {role:'guest',id:''};if(context.allowed)return {role:'admin',id};const member=await db().prepare('SELECT role FROM members WHERE email=?').bind(email).first<{role:string}>();return {role:member?.role==='staff'?'staff':'guest',id}}
async function hash(value:string){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))).map(b=>b.toString(16).padStart(2,'0')).join('')}
async function get(key:string,fallback:unknown){const row=await db().prepare('SELECT value FROM config WHERE key=?').bind(key).first<{value:string}>();return row?JSON.parse(row.value):fallback}
