function decorateGuide(list:any[]){const days:any={'live-music':[5,6],cinema:[3],walk:[2,4],'mini-disco':[0,1,2,3,4,5,6]};const times:any={'live-music':['21:30','23:00'],cinema:['21:00','23:00'],walk:['18:00','19:00'],'mini-disco':['20:30','21:00']};return list.map(g=>({...g,descriptionEn:g.descriptionEn||(g.description===(demoEnglish as any)[g.id]?.original?(demoEnglish as any)[g.id]?.descriptionEn:''),locationEn:g.locationEn||(g.location===(demoOriginal as any)[g.id]?.location?(demoEnglish as any)[g.id]?.locationEn:''),rulesEn:g.rulesEn||(g.rules===(demoOriginal as any)[g.id]?.rules?(demoEnglish as any)[g.id]?.rulesEn:''),timeEn:g.timeEn||(g.time===(demoOriginal as any)[g.id]?.time?(demoEnglish as any)[g.id]?.timeEn:''),bookable:g.bookable===undefined?['Rezervasyonlu','Kayıt gerekli','Ücretli'].includes(g.access):g.bookable,weekdays:g.weekdays===undefined?(days[g.id]||[]):g.weekdays,startTime:g.startTime===undefined?(times[g.id]?.[0]||''):g.startTime,endTime:g.endTime===undefined?(times[g.id]?.[1]||''):g.endTime}))}
async function guideData(){const saved=await get('guide_v2',null);if(saved!==null)return decorateGuide(saved);if(!main)return [];const settings=await get('settings',defaults);const demo=defaultGuide(settings.breakfast);const old=await get('guide',null);if(!Array.isArray(old))return decorateGuide(demo);const byId=new Map(demo.map(g=>[g.id,g]));return decorateGuide([...old.map((g:any)=>({...byId.get(g.id),...g})),...demo.filter(g=>!old.some((o:any)=>o.id===g.id))])}
