async function dispatch(r:Request,method:"GET"|"POST"){try{return await handlers(await hospitalityContext(r))[method](r)}catch(e){return Response.json({error:e instanceof Error?e.message:"Konaklama bulunamadı."},{status:403})}}
export const GET=(r:Request)=>dispatch(r,"GET");
export const POST=(r:Request)=>dispatch(r,"POST");
